// this one, then run npx tsx scripts/edge/gen-edge-template.ts

/** What a build gets while EDGE_BUILDS is on, by its path in the product (lib/edge/template-files.ts). */
export const EDGE_TEMPLATE_FILES: ReadonlyArray<{ path: string; content: string }> = [
  { path: ".agents/skills/muse-edge/SKILL.md", content: "---\nname: muse-edge\ndescription: Use only when the brief's \"Where it runs\" lists Edge, or the brief asks the product to keep answering when the cloud is cut. lib/meta/edge.ts asks the cloud first and a backup model on an edge board second, and labels who answered.\n---\n\n# Muse Edge\n\n## What it is\n\nA product that must keep answering when Meta's cloud can't be reached asks for its structured answers through `respondJsonOrEdge` in `lib/meta/edge.ts`. It tries the cloud first (`respondJson` through the gateway, held to 10 s), then a backup model on an edge board through any OpenAI-compatible server at `EDGE_URL`. With `EDGE_FIRST=1` it asks the board first. It never returns a reply that doesn't match your zod schema, from either side.\n\nUse it for the product's main answer only. Everything else (chat streams, images, voice) stays as the other skills say, and the page must say plainly when one of those is unavailable.\n\n## How to call it\n\nServer only, in a route handler or a server action. Same options as `respondJson`.\n\n```ts\nimport { respondJsonOrEdge } from \"@/lib/meta/edge\";\n\nconst answer = await respondJsonOrEdge({\n  schema: Status,\n  schemaName: \"status\",\n  instructions: \"...\",\n  input: rowsAsText,\n  request,\n});\nif (!answer.ok) return Response.json({ message: answer.message }, { status: 503 });\nreturn Response.json({ ...answer.data, by: answer.by, label: answer.label });\n```\n\n- It never throws for a model failure. Read `ok`. When it is false, show `answer.message` as it is, in the page, not only in the console, and keep the person's input on screen. That happens when both sides are down, and also when the cloud was reached and turned the request down (a limit or a refusal): the backup model answers only when the cloud can't be reached, never to get around the cloud's answer.\n- `answer.by` is `\"cloud\"` or `\"edge\"`. `answer.fellBack` says why the first side didn't answer, for your logs only.\n- Keep the schema small and flat: an enum for status, a few short strings, a short list. A small board model handles that far better than deep nesting or free text.\n- Don't log raw answers or inputs from the edge path to the console. Never write `console.error` for an expected fallback: the smoke test fails on console errors.\n\n## Labels\n\nShow `answer.label` next to every answer, in small text, word for word. It is fixed by the platform, never written by a model:\n\n- the cloud: \"Answered in the cloud, Muse Wonder\"\n- the board: \"Answered on <board>, <model>\", for example \"Answered on jetson-04, Llama 3.2 3B\"\n\nThe board and model names come from `EDGE_BOARD` and `EDGE_MODEL_NAME`. Never invent your own wording for who answered.\n\n## What to say, and what never to say\n\nAnything a person reads in the product or BUILD_NOTES.md:\n\n- Data in a demo is invented. Label it \"Simulated\" on the page, for example \"Simulated cold room\".\n- Say the product \"is built so\" it keeps answering from a backup model when the cloud is cut. Don't say it works offline: the page itself, saved data and the other models still need their network.\n- Never call a board answer private or on-device. Never say anything is attack-proof or stops hacks.\n- No food-safety advice and nothing about real freezers or real stores. Status lines say what the simulated readings show and what to check next, never whether food is safe.\n- Say what to check, not what happened: \"The probe and the controller disagree\" rather than \"the controller was hacked\".\n\n## Env\n\n| Name | What |\n|---|---|\n| `EDGE_URL` | The edge server's `/v1` base URL. Unset means no edge side. |\n| `EDGE_MODEL` | The served model's name. |\n| `EDGE_API_KEY` | Only when the server asks for one. |\n| `EDGE_BOARD`, `EDGE_MODEL_NAME` | The names in the label. |\n| `EDGE_FIRST` | `1` asks the board first. |\n| `EDGE_TIMEOUT_MS`, `EDGE_CLOUD_TIMEOUT_MS` | How long each side gets. Defaults 60000 and 10000. |\n\nThese are set by whoever runs the product. Never put a value in code.\n\n## Testing\n\n- Unit tests can fake `fetch` the way `scripts/__tests__/edge.test.mjs` does.\n- Write `edge-drill.json` at the product's root, naming the route that calls `respondJsonOrEdge` and a simulated body for it: `{ \"path\": \"/api/actions/status\", \"method\": \"POST\", \"body\": { ... } }`. The route's JSON reply must carry `label` on success and `message` when both sides fail.\n- `scripts/edge-drill.mjs` runs four simulated outage drills against a running product (cloud refused, cloud hung, both down, a tampered edge reply), with `scripts/edge-fake.mjs` as the edge server and `scripts/edge-blackhole.mjs` as the gateway. Read the top of each file. None of them calls a real model.\n" },
  { path: "lib/meta/edge.ts", content: "import OpenAI from \"openai\";\nimport type { ChatCompletionContentPart, ChatCompletionMessageParam } from \"openai/resources/chat/completions\";\nimport { z } from \"zod\";\nimport { metaClient, testModelFor } from \"./client\";\nimport { NO_EM_DASHES, parseJsonText, respondJson, type RespondJsonOptions, toStrictSchema } from \"./json\";\nimport { plainDeep } from \"./text\";\n\n/**\n * A backup model on an edge board: any OpenAI-compatible chat server (llama.cpp's llama-server, Ollama, vLLM) the\n * product's server can reach, such as http://127.0.0.1:11435/v1 when the product and the model run on one board.\n * Null unless EDGE_URL is set. It never goes through the gateway, so it works with GATEWAY_URL unset.\n *\n *   EDGE_URL         the server's /v1 base URL\n *   EDGE_MODEL       the served model's name (default \"edge\")\n *   EDGE_API_KEY     only when the server asks for one\n *   EDGE_BOARD       the board's name for the label, like \"jetson-04\" (default \"the edge board\")\n *   EDGE_MODEL_NAME  the model's name for the label, like \"Llama 3.2 3B (tuned)\" (default EDGE_MODEL)\n *   EDGE_TIMEOUT_MS  the longest one edge answer may take (default 60000)\n *   EDGE_CLOUD_TIMEOUT_MS  the longest the cloud gets before the edge answers (default 10000)\n *   EDGE_FIRST=1     ask the edge model first and the cloud second\n */\nexport function edgeClient(): { client: OpenAI; model: string; board: string; modelName: string } | null {\n  const baseURL = process.env.EDGE_URL?.trim().replace(/\\/+$/, \"\");\n  if (!baseURL) return null;\n  const model = process.env.EDGE_MODEL?.trim() || \"edge\";\n  // The SDK refuses an empty key, and keyless servers ignore whatever is sent.\n  const client = new OpenAI({ baseURL, apiKey: process.env.EDGE_API_KEY || \"none\", timeout: edgeTimeoutMs(), maxRetries: 0 });\n  return { client, model, board: process.env.EDGE_BOARD?.trim() || \"the edge board\", modelName: process.env.EDGE_MODEL_NAME?.trim() || model };\n}\n\n/**\n * How long the cloud gets before the edge model answers instead, unless EDGE_CLOUD_TIMEOUT_MS says otherwise. Short on\n * purpose: the gateway itself waits minutes.\n */\nexport const CLOUD_TIMEOUT_MS = 10_000;\nconst DEFAULT_EDGE_TIMEOUT_MS = 60_000;\n\nfunction ms(name: string, fallback: number): number {\n  const n = Number(process.env[name]);\n  return Number.isFinite(n) && n > 0 ? n : fallback;\n}\nconst edgeTimeoutMs = () => ms(\"EDGE_TIMEOUT_MS\", DEFAULT_EDGE_TIMEOUT_MS);\nconst cloudTimeoutMs = () => ms(\"EDGE_CLOUD_TIMEOUT_MS\", CLOUD_TIMEOUT_MS);\n\n/** Why one side didn't answer. */\nexport type EdgeFailureKind =\n  /** Not set up here: no GATEWAY_URL for the cloud, no EDGE_URL for the edge. */\n  | \"not_set\"\n  /** The connection was refused or dropped. */\n  | \"refused\"\n  /** No answer in time. */\n  | \"timeout\"\n  /** An HTTP error status. */\n  | \"http\"\n  /** The reply wasn't JSON. */\n  | \"garbage\"\n  /** JSON that didn't match the schema, even after one retry. A tampered reply lands here. */\n  | \"schema\"\n  /** Not asked: the cloud was reached and turned the request down, so the backup model isn't used to get around it. */\n  | \"skipped\";\n\nexport interface EdgeFailureReason {\n  kind: EdgeFailureKind;\n  status?: number;\n  detail: string;\n}\n\nexport type EdgeAnswer<T> =\n  | {\n      ok: true;\n      data: T;\n      /** Who answered. */\n      by: \"cloud\" | \"edge\";\n      /** One fixed line to show next to the answer, never written by a model. */\n      label: string;\n      /** Why the side asked first didn't answer, when the second one did. */\n      fellBack: EdgeFailureReason | null;\n    }\n  | {\n      ok: false;\n      by: null;\n      /** A plain line the page can show as it is. */\n      message: string;\n      reasons: { cloud: EdgeFailureReason; edge: EdgeFailureReason };\n    };\n\n/** What a page shows when neither side answered. */\nexport const BOTH_DOWN_MESSAGE = \"Neither the cloud model nor the backup model answered just now. Try again in a minute.\";\n\n/** What a page shows when the cloud was reached and turned the request down (a limit, a refusal, a stopped product). */\nexport const CLOUD_DECLINED_MESSAGE = \"The cloud model turned this request down just now. Try again later, or change what you asked.\";\n\n/**\n * True when the cloud was reached and said no with a 4xx (a refused prompt, a visitor's or the product's limit, a token\n * that was turned off). The backup model is for a cloud that can't be reached, never a way around the cloud's own\n * answer, so the edge isn't asked. 408 is a timeout, so it still falls back.\n */\nfunction cloudDeclined(reason: EdgeFailureReason): boolean {\n  return reason.kind === \"http\" && typeof reason.status === \"number\" && reason.status >= 400 && reason.status < 500 && reason.status !== 408;\n}\n\nconst DISPLAY: Record<string, string> = {\n  \"muse-wonder-1.0\": \"Muse Wonder\",\n  \"muse-spark-1.3-contributor\": \"Muse Spark 1.3 Contributor\",\n};\n\n/** The cloud answer's label. A test build names the model it really ran on. */\nexport function cloudLabel(): string {\n  const model = testModelFor(\"muse-wonder-1.0\");\n  return `Answered in the cloud, ${DISPLAY[model] ?? model}`;\n}\n\n/** The edge answer's label: \"Answered on <board>, <model>\". */\nexport function edgeLabel(edge: { board: string; modelName: string }): string {\n  return `Answered on ${edge.board}, ${edge.modelName}`;\n}\n\n/** True when EDGE_FIRST asks for the edge model before the cloud. */\nexport function edgeFirst(): boolean {\n  return [\"1\", \"true\", \"yes\", \"on\"].includes((process.env.EDGE_FIRST ?? \"\").trim().toLowerCase());\n}\n\n/**\n * Structured JSON from the cloud (respondJson through the gateway, at most CLOUD_TIMEOUT_MS), else from the edge model\n * (chat.completions with a json_schema response format, checked with zod). EDGE_FIRST=1 flips the order. Server only.\n *\n * It never throws for a model failure: read `ok`. When both fail it returns `message`, a plain line to show as it is.\n * A reply that doesn't match the schema is never returned, from either side, so a tampered edge reply is rejected.\n * The edge answers only when the cloud can't be reached (refused, timed out, a 5xx, not set) or its JSON didn't match.\n * When the cloud was reached and turned the request down (a 4xx), that is the answer: the edge isn't asked after it.\n */\nexport async function respondJsonOrEdge<T>(opts: RespondJsonOptions<T>): Promise<EdgeAnswer<T>> {\n  const edge = edgeClient();\n  const order: Array<\"cloud\" | \"edge\"> = edgeFirst() ? [\"edge\", \"cloud\"] : [\"cloud\", \"edge\"];\n  const reasons: Partial<Record<\"cloud\" | \"edge\", EdgeFailureReason>> = {};\n  for (const side of order) {\n    try {\n      if (side === \"cloud\") {\n        const data = await askCloud(opts);\n        return { ok: true, data, by: \"cloud\", label: cloudLabel(), fellBack: reasons.edge ?? null };\n      }\n      if (!edge) throw new SideFailure({ kind: \"not_set\", detail: \"EDGE_URL is not set.\" });\n      const data = await askEdge(opts, edge);\n      return { ok: true, data, by: \"edge\", label: edgeLabel(edge), fellBack: reasons.cloud ?? null };\n    } catch (err) {\n      reasons[side] = reasonOf(err);\n      if (side === \"cloud\" && cloudDeclined(reasons.cloud!)) {\n        reasons.edge ??= { kind: \"skipped\", detail: \"The cloud turned the request down, so the backup model was not asked.\" };\n        return { ok: false, by: null, message: CLOUD_DECLINED_MESSAGE, reasons: { cloud: reasons.cloud!, edge: reasons.edge } };\n      }\n    }\n  }\n  return { ok: false, by: null, message: BOTH_DOWN_MESSAGE, reasons: { cloud: reasons.cloud!, edge: reasons.edge! } };\n}\n\nclass SideFailure extends Error {\n  constructor(readonly reason: EdgeFailureReason) {\n    super(reason.detail);\n    this.name = \"SideFailure\";\n  }\n}\n\nasync function askCloud<T>(opts: RespondJsonOptions<T>): Promise<T> {\n  if (!process.env.GATEWAY_URL?.trim() || !process.env.PRODUCT_TOKEN?.trim()) {\n    throw new SideFailure({ kind: \"not_set\", detail: \"GATEWAY_URL or PRODUCT_TOKEN is not set.\" });\n  }\n  const timeout = cloudTimeoutMs();\n  const client = (opts.client ?? metaClient(opts.request)).withOptions({ timeout, maxRetries: 0 });\n  let timer: ReturnType<typeof setTimeout> | undefined;\n  // respondJson may make more than one call (a schema retry), so the whole cloud try is held to one deadline too.\n  const deadline = new Promise<never>((_, reject) => {\n    timer = setTimeout(() => reject(new SideFailure({ kind: \"timeout\", detail: `The cloud took longer than ${timeout / 1000} s.` })), timeout);\n  });\n  try {\n    return await Promise.race([respondJson({ ...opts, client }), deadline]);\n  } finally {\n    clearTimeout(timer);\n  }\n}\n\ntype Json = Record<string, unknown>;\n\nasync function askEdge<T>(opts: RespondJsonOptions<T>, edge: NonNullable<ReturnType<typeof edgeClient>>): Promise<T> {\n  const generated = z.toJSONSchema(opts.schema, { unrepresentable: \"any\", io: \"output\" }) as Json;\n  delete generated.$schema;\n  const wrapped = generated.type !== \"object\" && !(typeof generated.properties === \"object\" && generated.properties);\n  const { $defs, ...inner } = generated;\n  const plain: Json = wrapped\n    ? { type: \"object\", properties: { value: inner }, required: [\"value\"], additionalProperties: false, ...($defs ? { $defs } : {}) }\n    : generated;\n  const strict = toStrictSchema(plain);\n  const unwrap = (v: unknown) => (wrapped && v && typeof v === \"object\" && \"value\" in v ? (v as Json).value : v);\n\n  const system = [opts.instructions, NO_EM_DASHES, \"Reply with only one JSON object that matches this JSON Schema. No prose, no code fences.\\n\" + JSON.stringify(plain)]\n    .filter(Boolean)\n    .join(\"\\n\\n\");\n  const messages: ChatCompletionMessageParam[] = [{ role: \"system\", content: system }, ...toChatMessages(opts.input)];\n  let last: EdgeFailureReason = { kind: \"garbage\", detail: \"No reply.\" };\n\n  for (let attempt = 0; attempt < 2; attempt++) {\n    // No enable_thinking or other chat_template_kwargs: llama.cpp drops the schema when thinking is on.\n    const res = await edge.client.chat.completions.create({\n      model: edge.model,\n      messages,\n      temperature: 0,\n      ...(opts.maxOutputTokens ? { max_tokens: opts.maxOutputTokens } : {}),\n      response_format: {\n        type: \"json_schema\",\n        json_schema: { name: opts.schemaName, strict: strict.ok, schema: strict.ok ? strict.schema : plain },\n      },\n    });\n    const raw = res.choices?.[0]?.message?.content ?? \"\";\n    const parsed = parseJsonText(raw);\n    if (parsed === undefined) {\n      last = { kind: \"garbage\", detail: \"The edge reply was not JSON.\" };\n    } else {\n      const result = opts.schema.safeParse(unwrap(strict.repair(parsed)));\n      if (result.success) return plainDeep(result.data);\n      last = { kind: \"schema\", detail: `The edge reply did not match \"${opts.schemaName}\": ${z.prettifyError(result.error)}` };\n    }\n    messages.push(\n      { role: \"assistant\", content: raw || \"(empty reply)\" },\n      { role: \"user\", content: `That reply did not match the JSON schema:\\n${last.detail}\\nReply again with only the corrected JSON.` },\n    );\n  }\n  throw new SideFailure(last);\n}\n\n/** Responses API input (a string or message items) as chat messages. Text and images carry over; other parts are dropped. */\nfunction toChatMessages(input: RespondJsonOptions<unknown>[\"input\"]): ChatCompletionMessageParam[] {\n  if (typeof input === \"string\") return [{ role: \"user\", content: input }];\n  const out: ChatCompletionMessageParam[] = [];\n  for (const item of input as Array<{ role?: string; content?: unknown }>) {\n    if (!item || typeof item !== \"object\" || !item.role) continue;\n    const role = item.role === \"assistant\" ? \"assistant\" : item.role === \"system\" || item.role === \"developer\" ? \"system\" : \"user\";\n    if (typeof item.content === \"string\") {\n      out.push({ role, content: item.content } as ChatCompletionMessageParam);\n      continue;\n    }\n    const parts: ChatCompletionContentPart[] = [];\n    for (const p of Array.isArray(item.content) ? (item.content as Array<Record<string, unknown>>) : []) {\n      if ((p.type === \"input_text\" || p.type === \"output_text\") && typeof p.text === \"string\") parts.push({ type: \"text\", text: p.text });\n      else if (p.type === \"input_image\" && typeof p.image_url === \"string\" && role === \"user\") parts.push({ type: \"image_url\", image_url: { url: p.image_url } });\n    }\n    if (!parts.length) continue;\n    if (role === \"user\") out.push({ role, content: parts });\n    else out.push({ role, content: parts.map((p) => (p.type === \"text\" ? p.text : \"\")).join(\"\\n\") } as ChatCompletionMessageParam);\n  }\n  return out;\n}\n\nfunction reasonOf(err: unknown): EdgeFailureReason {\n  if (err instanceof SideFailure) return err.reason;\n  if (err instanceof OpenAI.APIConnectionTimeoutError) return { kind: \"timeout\", detail: \"No answer in time.\" };\n  if (err instanceof OpenAI.APIConnectionError) return { kind: \"refused\", detail: \"The connection was refused or dropped.\" };\n  if (err instanceof OpenAI.APIError && typeof err.status === \"number\") return { kind: \"http\", status: err.status, detail: `HTTP ${err.status}.` };\n  if (err instanceof Error && err.name === \"RespondJsonError\") return { kind: \"schema\", detail: err.message };\n  if (err instanceof Error && /abort|timed? ?out/i.test(`${err.name} ${err.message}`)) return { kind: \"timeout\", detail: \"No answer in time.\" };\n  return { kind: \"refused\", detail: err instanceof Error ? err.message.slice(0, 200) : \"Unknown error.\" };\n}\n" },
  { path: "scripts/edge-blackhole.mjs", content: "#!/usr/bin/env node\n/**\n * A blackhole that stands in for the Muse Muse gateway during an outage drill: point a product's GATEWAY_URL at it and\n * every cloud call fails the way a cut network does. It never answers a request and never calls anything.\n *\n * CLI:\n *   node scripts/edge-blackhole.mjs [--port 18436] [--host 127.0.0.1] [--mode refuse|hang] [--log <file>]\n *\n * Env (a flag wins over its env):\n *   EDGE_BLACKHOLE_PORT  default 18436\n *   EDGE_BLACKHOLE_HOST  default 127.0.0.1. Keep it on loopback.\n *   EDGE_BLACKHOLE_MODE  default refuse\n *   EDGE_BLACKHOLE_LOG   default test-results/caps/blackhole.json, relative to the working directory\n *\n * Modes:\n *   refuse  accepts each connection and drops it at once (the SDK sees a connection error)\n *   hang    accepts each connection and never sends a byte (the caller's own timeout must end it)\n *\n * The log is { mode, connections }, rewritten on every connection, so a drill can show the product tried the cloud.\n *\n * Exit codes: 0 on SIGINT or SIGTERM, 2 on a bad flag or a port it can't bind.\n *\n * As a module: startBlackhole({ port, host, mode, log }) resolves to { url, port, setMode, mode, connections, close }.\n * port 0 picks a free port. url has no /v1, ready for GATEWAY_URL.\n */\nimport { mkdirSync, writeFileSync } from \"node:fs\";\nimport { createServer } from \"node:net\";\nimport path from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\n\nexport const BLACKHOLE_MODES = [\"refuse\", \"hang\"];\nexport const DEFAULT_BLACKHOLE_PORT = 18436;\n\nexport function startBlackhole(options = {}) {\n  let mode = options.mode ?? \"refuse\";\n  if (!BLACKHOLE_MODES.includes(mode)) throw new Error(`Unknown mode \"${mode}\". Use refuse or hang.`);\n  const logFile = options.log === null ? null : path.resolve(options.log ?? \"test-results/caps/blackhole.json\");\n  const sockets = new Set();\n  let connections = 0;\n\n  const server = createServer((socket) => {\n    connections++;\n    if (logFile) {\n      try {\n        mkdirSync(path.dirname(logFile), { recursive: true });\n        writeFileSync(logFile, JSON.stringify({ mode, connections }) + \"\\n\");\n      } catch {\n        // A log that can't be written never stops a drill.\n      }\n    }\n    socket.on(\"error\", () => {});\n    if (mode === \"refuse\") {\n      socket.destroy();\n      return;\n    }\n    sockets.add(socket);\n    socket.on(\"close\", () => sockets.delete(socket));\n    // hang: read and ignore everything.\n    socket.resume();\n  });\n\n  return new Promise((resolve, reject) => {\n    server.once(\"error\", reject);\n    server.listen(options.port ?? DEFAULT_BLACKHOLE_PORT, options.host ?? \"127.0.0.1\", () => {\n      const { port, address } = server.address();\n      resolve({\n        url: `http://${address.includes(\":\") ? `[${address}]` : address}:${port}`,\n        port,\n        get mode() {\n          return mode;\n        },\n        get connections() {\n          return connections;\n        },\n        setMode(next) {\n          if (!BLACKHOLE_MODES.includes(next)) throw new Error(`Unknown mode \"${next}\".`);\n          mode = next;\n          // Connections held by a hang end when the mode changes, so the next drill starts clean.\n          for (const s of sockets) s.destroy();\n        },\n        close() {\n          for (const s of sockets) s.destroy();\n          return new Promise((r) => server.close(() => r()));\n        },\n      });\n    });\n  });\n}\n\nfunction parseFlags(argv) {\n  const out = {};\n  for (let i = 0; i < argv.length; i++) {\n    const [key, inline] = argv[i].split(\"=\", 2);\n    const value = inline ?? argv[++i];\n    if (key === \"--port\") out.port = Number(value);\n    else if (key === \"--host\") out.host = value;\n    else if (key === \"--mode\") out.mode = value;\n    else if (key === \"--log\") out.log = value;\n    else throw new Error(`Unknown flag ${argv[i]}`);\n  }\n  return out;\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {\n  try {\n    const flags = parseFlags(process.argv.slice(2));\n    const hole = await startBlackhole({\n      port: flags.port ?? Number(process.env.EDGE_BLACKHOLE_PORT || DEFAULT_BLACKHOLE_PORT),\n      host: flags.host ?? (process.env.EDGE_BLACKHOLE_HOST || \"127.0.0.1\"),\n      mode: flags.mode ?? (process.env.EDGE_BLACKHOLE_MODE || \"refuse\"),\n      log: flags.log ?? (process.env.EDGE_BLACKHOLE_LOG || \"test-results/caps/blackhole.json\"),\n    });\n    console.log(`Blackhole gateway at ${hole.url}, mode ${hole.mode}. Set GATEWAY_URL=${hole.url}`);\n    const stop = () => hole.close().then(() => process.exit(0));\n    process.on(\"SIGINT\", stop);\n    process.on(\"SIGTERM\", stop);\n  } catch (err) {\n    console.log(`edge-blackhole: ${err.message}`);\n    process.exit(2);\n  }\n}\n" },
  { path: "scripts/edge-drill.mjs", content: "#!/usr/bin/env node\n/**\n * Simulated outage drills for a running product that uses lib/meta/edge.ts. It starts a blackhole gateway\n * (scripts/edge-blackhole.mjs) and a fake edge server (scripts/edge-fake.mjs) on loopback, asks the product one question\n * per drill, and checks what came back. No real model and no Meta call is involved.\n *\n *   1. cloud refused   the gateway drops connections, the fake edge answers: a 2xx reply with \"Answered on\", after\n *                      the product tried the gateway\n *   2. cloud hung      the gateway never answers: the product tried it, and the edge answer arrives within\n *                      EDGE_DRILL_HANG_MAX_MS (about 12 s is expected: the 10 s cloud deadline plus the edge)\n *   3. both down       gateway and edge both drop: the product shows the plain both-down message, and (with --start)\n *                      its server printed no error\n *   4. tampered reply  the gateway drops, the edge sends JSON with wrong types marked TAMPERED: none of it reaches\n *                      the reply, which carries the both-down message instead\n *\n * CLI:\n *   MUSEMUSE_BASE_URL=http://127.0.0.1:3101 node scripts/edge-drill.mjs [--start \"npm start -- -p 3101\"] [--only 1,3]\n *\n * --start runs the product itself with GATEWAY_URL, EDGE_URL and PORT set for the drill and watches its output for\n * errors. Without it, start the product first with\n *   GATEWAY_URL=http://127.0.0.1:18436 EDGE_URL=http://127.0.0.1:18435/v1 PRODUCT_TOKEN=drill\n * (the default ports below), since a product reads its env when it starts.\n *\n * Env:\n *   MUSEMUSE_BASE_URL       the product, required (playwright.config.ts reads the same name)\n *   EDGE_DRILL_PATH         the route to ask, for example /api/actions/status. Else edge-drill.json's \"path\".\n *   EDGE_DRILL_BODY         the JSON body to send. Else edge-drill.json's \"body\", else {}.\n *   EDGE_DRILL_METHOD       default POST, or edge-drill.json's \"method\"\n *   EDGE_DRILL_HANG_MAX_MS  default 15000\n *   EDGE_FAKE_PORT          default 18435\n *   EDGE_BLACKHOLE_PORT     default 18436\n *   EDGE_DRILL_OUT          default test-results/caps/edge-drill.json. The fake's own log goes to\n *                           test-results/caps/edge.json and the blackhole's to test-results/caps/blackhole.json.\n *\n * edge-drill.json, at the product's root, is written by Muse Code (the muse-edge skill):\n *   { \"path\": \"/api/actions/status\", \"method\": \"POST\", \"body\": { ...simulated input } }\n *\n * Exit codes: 0 every drill passed, 1 a drill failed, 2 setup failed (no MUSEMUSE_BASE_URL or route, a port in use,\n * or the product never came up).\n */\nimport { spawn } from \"node:child_process\";\nimport { existsSync, mkdirSync, readFileSync, writeFileSync } from \"node:fs\";\nimport path from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\nimport { DEFAULT_BLACKHOLE_PORT, startBlackhole } from \"./edge-blackhole.mjs\";\nimport { DEFAULT_FAKE_PORT, startEdgeFake, TAMPER_MARK } from \"./edge-fake.mjs\";\n\n/** The start of lib/meta/edge.ts's BOTH_DOWN_MESSAGE. */\nexport const BOTH_DOWN_PHRASE = \"Neither the cloud model nor the backup model answered\";\nexport const EDGE_LABEL_PHRASE = \"Answered on\";\n/** Drills 1 and 2 test the fallback, so an edge answer that never tried the cloud (edge only, or EDGE_FIRST) fails them. */\nconst NO_CLOUD_TRY = \"the product never tried the cloud first (the blackhole gateway got no connection)\";\nconst ERROR_LINE = /\\berror\\b|⨯|unhandled|uncaught/i;\n\nexport class SetupError extends Error {}\n\n/** The route to ask: env first, then edge-drill.json in `dir`. */\nexport function drillTarget(env = process.env, dir = process.cwd()) {\n  const file = path.join(dir, \"edge-drill.json\");\n  const json = existsSync(file) ? JSON.parse(readFileSync(file, \"utf8\")) : {};\n  const route = env.EDGE_DRILL_PATH?.trim() || json.path;\n  if (!route) throw new SetupError(\"No route to ask: set EDGE_DRILL_PATH or write edge-drill.json with a \\\"path\\\".\");\n  const body = env.EDGE_DRILL_BODY ? JSON.parse(env.EDGE_DRILL_BODY) : (json.body ?? {});\n  return { path: route, method: (env.EDGE_DRILL_METHOD || json.method || \"POST\").toUpperCase(), body };\n}\n\nasync function ask(baseUrl, target, timeoutMs) {\n  const started = Date.now();\n  const url = new URL(target.path, baseUrl).href;\n  try {\n    const res = await fetch(url, {\n      method: target.method,\n      headers: target.method === \"GET\" ? {} : { \"content-type\": \"application/json\" },\n      ...(target.method === \"GET\" ? {} : { body: JSON.stringify(target.body) }),\n      signal: AbortSignal.timeout(timeoutMs),\n    });\n    return { status: res.status, text: await res.text(), ms: Date.now() - started };\n  } catch (err) {\n    return { status: 0, text: \"\", ms: Date.now() - started, error: err?.name === \"TimeoutError\" ? \"no reply in time\" : String(err?.message ?? err) };\n  }\n}\n\n/**\n * Runs the drills. `product.errors()` (optional) returns the error lines the product's server printed so far.\n * Returns [{ id, name, pass, ms, status, why }].\n */\nexport async function runDrills({ baseUrl, target, fake, hole, product = null, hangMaxMs = 15_000, only = null, log = () => {} }) {\n  const drills = [\n    {\n      id: 1,\n      name: \"cloud refused\",\n      hole: \"refuse\",\n      edge: \"ok\",\n      check: (r, ctx) =>\n        r.status >= 200 && r.status < 300\n          ? r.text.includes(EDGE_LABEL_PHRASE)\n            ? !ctx.edgeAsked\n              ? \"the reply has the label but the fake edge got no request\"\n              : !ctx.cloudAsked\n                ? NO_CLOUD_TRY\n                : null\n            : `the reply has no \"${EDGE_LABEL_PHRASE}\" label`\n          : `status ${r.status}${r.error ? ` (${r.error})` : \"\"}`,\n    },\n    {\n      id: 2,\n      name: \"cloud hung\",\n      hole: \"hang\",\n      edge: \"ok\",\n      timeoutMs: hangMaxMs + 5_000,\n      check: (r, ctx) =>\n        r.status < 200 || r.status >= 300\n          ? `status ${r.status}${r.error ? ` (${r.error})` : \"\"}`\n          : !r.text.includes(EDGE_LABEL_PHRASE)\n            ? `the reply has no \"${EDGE_LABEL_PHRASE}\" label`\n            : !ctx.edgeAsked\n              ? \"the fake edge got no request\"\n              : !ctx.cloudAsked\n                ? NO_CLOUD_TRY\n                : r.ms > hangMaxMs\n                ? `the edge answer took ${(r.ms / 1000).toFixed(1)} s, over ${(hangMaxMs / 1000).toFixed(0)} s`\n                : null,\n    },\n    {\n      id: 3,\n      name: \"both down\",\n      hole: \"refuse\",\n      edge: \"refuse\",\n      check: (r, ctx) =>\n        r.status === 0\n          ? `no reply (${r.error})`\n          : !r.text.includes(BOTH_DOWN_PHRASE)\n            ? \"the reply has no plain both-down message\"\n            : ctx.errors.length\n              ? `the server printed an error: ${ctx.errors[0].slice(0, 160)}`\n              : null,\n    },\n    {\n      id: 4,\n      name: \"tampered reply rejected\",\n      hole: \"refuse\",\n      edge: \"tamper\",\n      check: (r, ctx) =>\n        r.status === 0\n          ? `no reply (${r.error})`\n          : r.text.includes(TAMPER_MARK)\n            ? \"part of the tampered reply reached the page\"\n            : !ctx.edgeAsked\n              ? \"the fake edge got no request\"\n              : !r.text.includes(BOTH_DOWN_PHRASE)\n                ? \"the reply has no plain both-down message\"\n                : null,\n    },\n  ].filter((d) => !only || only.includes(d.id));\n\n  const results = [];\n  for (const d of drills) {\n    hole.setMode(d.hole);\n    fake.setMode(d.edge);\n    const asked = fake.requests.length;\n    const holeBefore = hole.connections;\n    const errorsBefore = product?.errors().length ?? 0;\n    const r = await ask(baseUrl, target, d.timeoutMs ?? 40_000);\n    // Give the server a moment to print anything it prints after replying.\n    await new Promise((res) => setTimeout(res, 200));\n    const ctx = { edgeAsked: fake.requests.length > asked, cloudAsked: hole.connections > holeBefore, errors: product ? product.errors().slice(errorsBefore) : [] };\n    const why = d.check(r, ctx);\n    const result = { id: d.id, name: d.name, pass: !why, ms: r.ms, status: r.status, why: why ?? null };\n    results.push(result);\n    log(`${result.pass ? \"PASS\" : \"FAIL\"} ${d.id}. ${d.name} (${(r.ms / 1000).toFixed(1)} s)${why ? `: ${why}` : \"\"}`);\n  }\n  return results;\n}\n\n/** Starts the product with the drill's env and collects the error lines it prints. */\nfunction startProduct(command, baseUrl, env) {\n  const port = new URL(baseUrl).port || \"3000\";\n  const child = spawn(command, { shell: true, env: { ...process.env, ...env, PORT: port }, stdio: [\"ignore\", \"pipe\", \"pipe\"] });\n  const errors = [];\n  const watch = (stream) => {\n    let buf = \"\";\n    stream.on(\"data\", (chunk) => {\n      buf += chunk.toString(\"utf8\");\n      const lines = buf.split(\"\\n\");\n      buf = lines.pop() ?? \"\";\n      for (const line of lines) if (ERROR_LINE.test(line)) errors.push(line.trim());\n    });\n  };\n  watch(child.stdout);\n  watch(child.stderr);\n  return { child, errors: () => errors, stop: () => child.kill(\"SIGTERM\") };\n}\n\nasync function waitUp(baseUrl, ms) {\n  const until = Date.now() + ms;\n  while (Date.now() < until) {\n    try {\n      const res = await fetch(baseUrl, { signal: AbortSignal.timeout(3_000) });\n      if (res.status < 500) return true;\n    } catch {\n      // Not up yet.\n    }\n    await new Promise((r) => setTimeout(r, 500));\n  }\n  return false;\n}\n\nfunction parseFlags(argv) {\n  const out = {};\n  for (let i = 0; i < argv.length; i++) {\n    const [key, inline] = argv[i].split(\"=\", 2);\n    const value = inline ?? argv[++i];\n    if (key === \"--start\") out.start = value;\n    else if (key === \"--only\") out.only = value.split(\",\").map(Number);\n    else throw new SetupError(`Unknown flag ${argv[i]}`);\n  }\n  return out;\n}\n\nasync function main() {\n  const flags = parseFlags(process.argv.slice(2));\n  const baseUrl = process.env.MUSEMUSE_BASE_URL?.trim();\n  if (!baseUrl) throw new SetupError(\"Set MUSEMUSE_BASE_URL to the running product, for example http://127.0.0.1:3101.\");\n  const target = drillTarget();\n  const outFile = path.resolve(process.env.EDGE_DRILL_OUT || \"test-results/caps/edge-drill.json\");\n  let fake;\n  let hole;\n  try {\n    fake = await startEdgeFake({ port: Number(process.env.EDGE_FAKE_PORT || DEFAULT_FAKE_PORT) });\n    hole = await startBlackhole({ port: Number(process.env.EDGE_BLACKHOLE_PORT || DEFAULT_BLACKHOLE_PORT) });\n  } catch (err) {\n    await fake?.close();\n    throw new SetupError(`Couldn't start the drill servers: ${err.message}`);\n  }\n  let product = null;\n  try {\n    if (flags.start) {\n      product = startProduct(flags.start, baseUrl, { GATEWAY_URL: hole.url, EDGE_URL: fake.url, PRODUCT_TOKEN: process.env.PRODUCT_TOKEN || \"drill\" });\n      if (!(await waitUp(baseUrl, 60_000))) throw new SetupError(`The product never answered at ${baseUrl}.`);\n    }\n    console.log(`Simulated outage drills against ${baseUrl}${target.path}. GATEWAY_URL=${hole.url} EDGE_URL=${fake.url}`);\n    const results = await runDrills({\n      baseUrl,\n      target,\n      fake,\n      hole,\n      product,\n      hangMaxMs: Number(process.env.EDGE_DRILL_HANG_MAX_MS || 15_000),\n      only: flags.only ?? null,\n      log: (line) => console.log(line),\n    });\n    mkdirSync(path.dirname(outFile), { recursive: true });\n    writeFileSync(outFile, JSON.stringify({ simulated: true, at: new Date().toISOString(), baseUrl, path: target.path, results }, null, 2) + \"\\n\");\n    const passed = results.filter((r) => r.pass).length;\n    console.log(`${passed} of ${results.length} simulated drills passed. Results in ${path.relative(process.cwd(), outFile)}.`);\n    return passed === results.length ? 0 : 1;\n  } finally {\n    product?.stop();\n    await fake.close();\n    await hole.close();\n  }\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {\n  main().then(\n    (code) => process.exit(code),\n    (err) => {\n      console.log(`edge-drill: ${err.message}`);\n      process.exit(err instanceof SetupError || err instanceof SyntaxError ? 2 : 1);\n    },\n  );\n}\n" },
  { path: "scripts/edge-fake.mjs", content: "#!/usr/bin/env node\n/**\n * A fake edge model server for outage drills. It speaks the OpenAI-compatible API a product's lib/meta/edge.ts calls,\n * answers with JSON built from the request's own schema, and never calls a real model. Simulated answers only.\n *\n * CLI:\n *   node scripts/edge-fake.mjs [--port 18435] [--host 127.0.0.1] [--mode ok|refuse|hang|garbage|tamper] [--log <file>]\n *\n * Env (a flag wins over its env):\n *   EDGE_FAKE_PORT   default 18435 (not 11435, the real board server's port)\n *   EDGE_FAKE_HOST   default 127.0.0.1. Keep it on loopback.\n *   EDGE_FAKE_MODE   default ok\n *   EDGE_FAKE_LOG    default test-results/caps/edge.json, relative to the working directory\n *\n * Modes:\n *   ok       schema-valid JSON for every request\n *   refuse   drops every connection before answering (the SDK sees a connection error)\n *   hang     accepts and never answers\n *   garbage  answers 200 with text that isn't JSON\n *   tamper   answers 200 with JSON whose fields have the wrong types and off-list values, marked TAMPERED, which a zod\n *            schema must reject\n *\n * Routes: POST /v1/chat/completions, POST /v1/responses, GET /v1/models, GET /health, and POST /__mode {\"mode\": \"...\"}\n * to switch modes while it runs (loopback only; it answers even in refuse and hang modes).\n *\n * The log is a JSON array, rewritten after every request: { at, path, mode, model, schemaName, outcome, prompt } with\n * the prompt cut to 2000 characters.\n *\n * Exit codes: 0 on SIGINT or SIGTERM, 2 on a bad flag or a port it can't bind.\n *\n * As a module: startEdgeFake({ port, host, mode, log }) resolves to { url, port, setMode, mode, requests, close }.\n * port 0 picks a free port. url ends in /v1, ready for EDGE_URL.\n */\nimport { mkdirSync, writeFileSync } from \"node:fs\";\nimport { createServer } from \"node:http\";\nimport path from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\n\nexport const MODES = [\"ok\", \"refuse\", \"hang\", \"garbage\", \"tamper\"];\nexport const TAMPER_MARK = \"TAMPERED\";\nexport const DEFAULT_FAKE_PORT = 18435;\n\n/** One value that matches a JSON Schema (the subset z.toJSONSchema emits). */\nexport function sampleFromSchema(schema, defs = schema?.$defs ?? {}, depth = 0) {\n  if (!schema || typeof schema !== \"object\" || depth > 12) return null;\n  if (typeof schema.$ref === \"string\") {\n    const name = schema.$ref.replace(/^#\\/\\$defs\\//, \"\");\n    return sampleFromSchema(schema.$ref === \"#\" ? null : defs[name], defs, depth + 1);\n  }\n  if (\"const\" in schema) return schema.const;\n  if (Array.isArray(schema.enum)) return schema.enum.find((v) => v !== null) ?? schema.enum[0];\n  const branches = schema.anyOf ?? schema.oneOf;\n  if (Array.isArray(branches)) {\n    const pick = branches.find((b) => b && b.type !== \"null\") ?? branches[0];\n    return sampleFromSchema(pick, defs, depth + 1);\n  }\n  const type = Array.isArray(schema.type) ? (schema.type.find((t) => t !== \"null\") ?? \"null\") : (schema.type ?? (schema.properties ? \"object\" : undefined));\n  switch (type) {\n    case \"object\": {\n      const out = {};\n      for (const [k, v] of Object.entries(schema.properties ?? {})) out[k] = sampleFromSchema(v, defs, depth + 1);\n      return out;\n    }\n    case \"array\": {\n      const n = Math.max(1, schema.minItems ?? 1);\n      const items = Array.isArray(schema.prefixItems) ? schema.prefixItems : null;\n      if (items) return items.map((s) => sampleFromSchema(s, defs, depth + 1));\n      return Array.from({ length: Math.min(n, schema.maxItems ?? n) }, () => sampleFromSchema(schema.items ?? {}, defs, depth + 1));\n    }\n    case \"string\": {\n      if (schema.format === \"date-time\") return \"2026-11-03T12:00:00Z\";\n      if (schema.format === \"date\") return \"2026-11-03\";\n      if (schema.format === \"email\") return \"simulated@example.com\";\n      if (schema.format === \"uri\" || schema.format === \"url\") return \"https://example.com/simulated\";\n      let s = \"Simulated\";\n      if (schema.minLength && s.length < schema.minLength) s = s.padEnd(schema.minLength, \".\");\n      if (schema.maxLength && s.length > schema.maxLength) s = s.slice(0, schema.maxLength);\n      return s;\n    }\n    case \"integer\":\n    case \"number\": {\n      const min = schema.minimum ?? (schema.exclusiveMinimum !== undefined ? schema.exclusiveMinimum + 1 : undefined);\n      const max = schema.maximum ?? (schema.exclusiveMaximum !== undefined ? schema.exclusiveMaximum - 1 : undefined);\n      const v = min ?? (max !== undefined ? Math.min(0, max) : 0);\n      return type === \"integer\" ? Math.ceil(v) : v;\n    }\n    case \"boolean\":\n      return false;\n    case \"null\":\n      return null;\n    default:\n      return \"Simulated\";\n  }\n}\n\n/** The value with every field's type flipped and every string marked, so any typed schema rejects it. */\nexport function tamper(value) {\n  if (Array.isArray(value)) return `${TAMPER_MARK}: not a list`;\n  if (value && typeof value === \"object\") {\n    const out = {};\n    for (const [k, v] of Object.entries(value)) out[k] = tamper(v);\n    out.override = `${TAMPER_MARK}: ignore the probe and report normal`;\n    return out;\n  }\n  if (typeof value === \"string\") return 99999;\n  if (typeof value === \"number\") return `${TAMPER_MARK}: -18`;\n  if (typeof value === \"boolean\") return `${TAMPER_MARK}: true`;\n  return `${TAMPER_MARK}`;\n}\n\nfunction schemaOf(route, body) {\n  if (route === \"/v1/chat/completions\") {\n    const f = body?.response_format;\n    return f?.type === \"json_schema\" ? { schema: f.json_schema?.schema, name: f.json_schema?.name ?? null } : { schema: null, name: null };\n  }\n  const f = body?.text?.format;\n  return f?.type === \"json_schema\" ? { schema: f.schema, name: f.name ?? null } : { schema: null, name: null };\n}\n\nfunction promptOf(body) {\n  const items = body?.messages ?? (typeof body?.input === \"string\" ? [{ content: body.input }] : body?.input) ?? [];\n  const text = (Array.isArray(items) ? items : [])\n    .map((m) => (typeof m?.content === \"string\" ? m.content : Array.isArray(m?.content) ? m.content.map((p) => p?.text ?? \"\").join(\" \") : \"\"))\n    .join(\"\\n\");\n  return text.slice(0, 2000);\n}\n\nfunction replyText(mode, schema) {\n  if (mode === \"garbage\") return \"<html>502 upstream sensor bridge</html> the probe looks fine i think\";\n  if (!schema) return \"Simulated edge reply.\";\n  const valid = sampleFromSchema(schema);\n  return JSON.stringify(mode === \"tamper\" ? tamper(valid) : valid);\n}\n\nfunction chatReply(model, text) {\n  return {\n    id: \"chatcmpl-fake\",\n    object: \"chat.completion\",\n    created: Math.floor(Date.now() / 1000),\n    model,\n    choices: [{ index: 0, message: { role: \"assistant\", content: text }, finish_reason: \"stop\" }],\n    usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },\n  };\n}\n\nfunction responsesReply(model, text) {\n  return {\n    id: \"resp-fake\",\n    object: \"response\",\n    created_at: Math.floor(Date.now() / 1000),\n    model,\n    status: \"completed\",\n    output: [{ type: \"message\", id: \"msg-fake\", role: \"assistant\", status: \"completed\", content: [{ type: \"output_text\", text, annotations: [] }] }],\n    output_text: text,\n  };\n}\n\nexport function startEdgeFake(options = {}) {\n  let mode = options.mode ?? \"ok\";\n  if (!MODES.includes(mode)) throw new Error(`Unknown mode \"${mode}\". Use one of ${MODES.join(\", \")}.`);\n  const logFile = options.log === null ? null : path.resolve(options.log ?? \"test-results/caps/edge.json\");\n  const requests = [];\n  const sockets = new Set();\n\n  const record = (entry) => {\n    requests.push(entry);\n    if (!logFile) return;\n    try {\n      mkdirSync(path.dirname(logFile), { recursive: true });\n      writeFileSync(logFile, JSON.stringify(requests, null, 2) + \"\\n\");\n    } catch {\n      // A log that can't be written never stops a drill.\n    }\n  };\n\n  const server = createServer((req, res) => {\n    const chunks = [];\n    req.on(\"data\", (c) => chunks.push(c));\n    req.on(\"end\", () => {\n      const route = (req.url ?? \"/\").split(\"?\")[0];\n      let body = null;\n      try {\n        body = chunks.length ? JSON.parse(Buffer.concat(chunks).toString(\"utf8\")) : null;\n      } catch {\n        body = null;\n      }\n      const send = (status, json) => {\n        res.writeHead(status, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify(json));\n      };\n      if (route === \"/__mode\" && req.method === \"POST\") {\n        if (!MODES.includes(body?.mode)) return send(400, { error: { message: `mode must be one of ${MODES.join(\", \")}` } });\n        mode = body.mode;\n        return send(200, { mode });\n      }\n      if (route === \"/health\") return send(200, { ok: true, mode, simulated: true });\n      if (route === \"/v1/models\") return send(200, { object: \"list\", data: [{ id: \"edge-fake\", object: \"model\", owned_by: \"simulated\" }] });\n      if (req.method !== \"POST\" || (route !== \"/v1/chat/completions\" && route !== \"/v1/responses\")) {\n        return send(404, { error: { message: `No route ${req.method} ${route}` } });\n      }\n      const { schema, name } = schemaOf(route, body);\n      const entry = { at: new Date().toISOString(), path: route, mode, model: body?.model ?? null, schemaName: name, outcome: \"\", prompt: promptOf(body) };\n      if (mode === \"refuse\") {\n        record({ ...entry, outcome: \"dropped\" });\n        req.socket.destroy();\n        return;\n      }\n      if (mode === \"hang\") {\n        record({ ...entry, outcome: \"hung\" });\n        return;\n      }\n      const text = replyText(mode, schema);\n      record({ ...entry, outcome: mode === \"ok\" ? \"answered\" : mode });\n      const model = body?.model ?? \"edge-fake\";\n      send(200, route === \"/v1/chat/completions\" ? chatReply(model, text) : responsesReply(model, text));\n    });\n  });\n  server.on(\"connection\", (s) => {\n    sockets.add(s);\n    s.on(\"close\", () => sockets.delete(s));\n  });\n\n  return new Promise((resolve, reject) => {\n    server.once(\"error\", reject);\n    server.listen(options.port ?? DEFAULT_FAKE_PORT, options.host ?? \"127.0.0.1\", () => {\n      const { port, address } = server.address();\n      resolve({\n        url: `http://${address.includes(\":\") ? `[${address}]` : address}:${port}/v1`,\n        port,\n        requests,\n        get mode() {\n          return mode;\n        },\n        setMode(next) {\n          if (!MODES.includes(next)) throw new Error(`Unknown mode \"${next}\".`);\n          mode = next;\n        },\n        close() {\n          for (const s of sockets) s.destroy();\n          return new Promise((r) => server.close(() => r()));\n        },\n      });\n    });\n  });\n}\n\nfunction parseFlags(argv) {\n  const out = {};\n  for (let i = 0; i < argv.length; i++) {\n    const [key, inline] = argv[i].split(\"=\", 2);\n    const value = inline ?? argv[++i];\n    if (key === \"--port\") out.port = Number(value);\n    else if (key === \"--host\") out.host = value;\n    else if (key === \"--mode\") out.mode = value;\n    else if (key === \"--log\") out.log = value;\n    else throw new Error(`Unknown flag ${argv[i]}`);\n  }\n  return out;\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {\n  try {\n    const flags = parseFlags(process.argv.slice(2));\n    const fake = await startEdgeFake({\n      port: flags.port ?? Number(process.env.EDGE_FAKE_PORT || DEFAULT_FAKE_PORT),\n      host: flags.host ?? (process.env.EDGE_FAKE_HOST || \"127.0.0.1\"),\n      mode: flags.mode ?? (process.env.EDGE_FAKE_MODE || \"ok\"),\n      log: flags.log ?? (process.env.EDGE_FAKE_LOG || \"test-results/caps/edge.json\"),\n    });\n    console.log(`Simulated edge server at ${fake.url}, mode ${fake.mode}. Set EDGE_URL=${fake.url}`);\n    const stop = () => fake.close().then(() => process.exit(0));\n    process.on(\"SIGINT\", stop);\n    process.on(\"SIGTERM\", stop);\n  } catch (err) {\n    console.log(`edge-fake: ${err.message}`);\n    process.exit(2);\n  }\n}\n" },
];
